import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.cZsgxozV.js";var i=JSON.parse(`{"title":"Desktop code signing","description":"","frontmatter":{},"headers":[],"relativePath":"desktop/code-signing.md","filePath":"desktop/code-signing.md"}`),a={name:`desktop/code-signing.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="desktop-code-signing" tabindex="-1">Desktop code signing <a class="header-anchor" href="#desktop-code-signing" aria-label="Permalink to “Desktop code signing”">​</a></h1><p>DocuHaim desktop releases are built by <a href="../../.github/workflows/release-tauri.yml"><code>.github/workflows/release-tauri.yml</code></a>.</p><p><strong>If signing secrets are missing, the workflow still uploads unsigned DMG / NSIS artifacts.</strong> Gatekeeper (macOS) and SmartScreen (Windows) will warn users until secrets are configured.</p><h2 id="version-source-of-truth" tabindex="-1">Version source of truth <a class="header-anchor" href="#version-source-of-truth" aria-label="Permalink to “Version source of truth”">​</a></h2><p>Desktop app version is owned by root <a href="../../package.json"><code>package.json</code></a> <code>version</code>.</p><table tabindex="0"><thead><tr><th>Consumer</th><th>How it inherits</th></tr></thead><tbody><tr><td><code>src-tauri/tauri.conf.json</code></td><td><code>&quot;version&quot;: &quot;../package.json&quot;</code></td></tr><tr><td><code>src-tauri/Cargo.toml</code></td><td><code>bun run sync:tauri-version</code> (before <code>tauri:dev</code> / <code>tauri:build</code>)</td></tr><tr><td>GitHub Release tag / name</td><td><code>release-tauri.yml</code> reads <code>package.json</code> into <code>VERSION</code></td></tr></tbody></table><p>Bump <code>package.json</code> version in the repo before running the release workflow. The workflow does <strong>not</strong> take a version input.</p><h2 id="trigger" tabindex="-1">Trigger <a class="header-anchor" href="#trigger" aria-label="Permalink to “Trigger”">​</a></h2><p>GitHub → Actions → <strong>Release Tauri</strong> → Run workflow (optional: mark prerelease).</p><h2 id="optional-secrets-1-1-with-the-workflow" tabindex="-1">Optional secrets (1:1 with the workflow) <a class="header-anchor" href="#optional-secrets-1-1-with-the-workflow" aria-label="Permalink to “Optional secrets (1:1 with the workflow)”">​</a></h2><table tabindex="0"><thead><tr><th>Secret</th><th>Platform</th><th>Purpose</th></tr></thead><tbody><tr><td><code>APPLE_CERTIFICATE</code></td><td>macOS</td><td>Base64-encoded <code>.p12</code> Developer ID Application certificate</td></tr><tr><td><code>APPLE_CERTIFICATE_PASSWORD</code></td><td>macOS</td><td>Password for the <code>.p12</code></td></tr><tr><td><code>APPLE_SIGNING_IDENTITY</code></td><td>macOS</td><td>e.g. <code>Developer ID Application: Your Name (TEAMID)</code></td></tr><tr><td><code>APPLE_ID</code></td><td>macOS</td><td>Apple ID email for notarization</td></tr><tr><td><code>APPLE_PASSWORD</code></td><td>macOS</td><td>App-specific password (not your Apple ID password)</td></tr><tr><td><code>APPLE_TEAM_ID</code></td><td>macOS</td><td>10-character Team ID</td></tr><tr><td><code>WINDOWS_CERTIFICATE</code></td><td>Windows</td><td>Base64-encoded Authenticode PFX / P12</td></tr><tr><td><code>WINDOWS_CERTIFICATE_PASSWORD</code></td><td>Windows</td><td>PFX password</td></tr><tr><td><code>TAURI_SIGNING_PRIVATE_KEY</code></td><td>macOS / Windows</td><td>Updater signing private key (contents of <code>.key</code> file, or base64)</td></tr><tr><td><code>TAURI_SIGNING_PRIVATE_KEY_PASSWORD</code></td><td>macOS / Windows</td><td>Optional password when the updater private key is encrypted</td></tr></tbody></table><p>Empty secrets are ignored; <strong>do not</strong> set <code>APPLE_CERTIFICATE</code> (or other signing secrets) with placeholder or broken values — Tauri will attempt import/codesign and the workflow fails with <code>security import</code> / <code>SecKeychainItemImport</code> errors. Remove invalid secrets or fix the <code>.p12</code> encoding and password.</p><h2 id="auto-update-tauri-updater" tabindex="-1">Auto-update (Tauri updater) <a class="header-anchor" href="#auto-update-tauri-updater" aria-label="Permalink to “Auto-update (Tauri updater)”">​</a></h2><p>Desktop auto-update uses GitHub Releases as the update endpoint (<code>latest.json</code> on each release). The public key is committed in <code>src-tauri/tauri.conf.json</code> (see also <code>src-tauri/updater.key.pub</code>).</p><h3 id="generate-or-rotate-updater-keys" tabindex="-1">Generate or rotate updater keys <a class="header-anchor" href="#generate-or-rotate-updater-keys" aria-label="Permalink to “Generate or rotate updater keys”">​</a></h3><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bunx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tauri</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> signer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> generate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -w</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.tauri/docuhaim.key</span></span></code></pre></div><ul><li>Copy the <strong>public</strong> key output into <code>plugins.updater.pubkey</code> in <code>src-tauri/tauri.conf.json</code> and <code>src-tauri/updater.key.pub</code>.</li><li>Store the <strong>private</strong> key in GitHub Secrets as <code>TAURI_SIGNING_PRIVATE_KEY</code> (paste the key file contents, or base64-encode the file).</li><li>If the key has a password, set <code>TAURI_SIGNING_PRIVATE_KEY_PASSWORD</code>.</li></ul><p>The release workflow passes these secrets to <code>tauri-action</code>, which uploads signed updater artifacts and <code>latest.json</code> alongside DMG / NSIS installers.</p><p>Without <code>TAURI_SIGNING_PRIVATE_KEY</code>, releases still build but auto-update signatures will not match the embedded public key — configure the secret before shipping updater-enabled builds to users.</p><h2 id="macos-setup" tabindex="-1">macOS setup <a class="header-anchor" href="#macos-setup" aria-label="Permalink to “macOS setup”">​</a></h2><ol><li>Create a <strong>Developer ID Application</strong> certificate in your Apple Developer account.</li><li>Export as <code>.p12</code> from Keychain Access.</li><li>Encode for GitHub Secrets:</li></ol><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">base64</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> DeveloperID.p12</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> pbcopy</span></span></code></pre></div><ol start="4"><li>Create an <a href="https://appleid.apple.com/" target="_blank" rel="noreferrer">app-specific password</a> for notarization → <code>APPLE_PASSWORD</code>.</li><li>Set <code>APPLE_SIGNING_IDENTITY</code> to the exact Common Name of the certificate.</li><li>Set <code>APPLE_TEAM_ID</code> from <a href="https://developer.apple.com/account" target="_blank" rel="noreferrer">Membership details</a>.</li></ol><p>After the first signed release, verify:</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">spctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --assess</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --type</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> execute</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/DocuHaim.app</span></span></code></pre></div><h2 id="windows-setup" tabindex="-1">Windows setup <a class="header-anchor" href="#windows-setup" aria-label="Permalink to “Windows setup”">​</a></h2><ol><li>Obtain an Authenticode code-signing certificate (PFX).</li><li>Encode:</li></ol><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># Git Bash / WSL</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">base64</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -w0</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> certificate.pfx</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> certificate.b64</span></span></code></pre></div><ol start="3"><li>Store as <code>WINDOWS_CERTIFICATE</code> and <code>WINDOWS_CERTIFICATE_PASSWORD</code>.</li></ol><p>Tauri NSIS signing uses these when present. Confirm the built installer is signed with <code>signtool verify /pa DocuHaim_*_x64-setup.exe</code> when available.</p><h2 id="local-unsigned-build" tabindex="-1">Local unsigned build <a class="header-anchor" href="#local-unsigned-build" aria-label="Permalink to “Local unsigned build”">​</a></h2><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tauri:build</span></span></code></pre></div><p>Artifacts appear under <code>src-tauri/target/release/bundle/</code> (<code>dmg/</code>, <code>nsis/</code>).</p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to “Notes”">​</a></h2><ul><li>Web (GitHub Pages) deploy is unchanged (<code>deploy.yml</code>).</li><li>Desktop builds use <code>VITE_ELECTRON=true</code> / <code>build:tauri</code> (HashRouter, no PWA) so the same SPA ships in the shell.</li><li><code>.md</code> / <code>.markdown</code> file associations are registered in <code>src-tauri/tauri.conf.json</code>. Composite <code>.enc.md</code> opens as markdown via the same association on most OSes.</li><li><strong>Touch ID / Windows Hello unlock</strong> uses <code>tauri-plugin-biometry</code> (not WebView WebAuthn). On macOS, keychain-backed storage needs a properly signed app (Developer ID); unsigned local builds may fail to persist biometric secrets.</li></ul>`,35)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};